require_once __DIR__.'/../include/session.php';require_once __DIR__.'/../include/config.php';if(empty($_SESSION['user'])){header('Location: '.BASE_URL.'/index.php');exit;}if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: '.BASE_URL.'/ubah_password.php');exit;}$token=$_POST['csrf_token']??'';if(!is_string($token)||empty($_SESSION['csrf_token'])||!hash_equals($_SESSION['csrf_token'],$token)){http_response_code(419);exit('Formulir kedaluwarsa.');}
$userId=(int)$_SESSION['user']['id'];$old=(string)($_POST['password_lama']??'');$new=(string)($_POST['password_baru']??'');$confirm=(string)($_POST['konfirmasi']??'');$stmt=$conn->prepare('SELECT password_hash FROM users WHERE id=? LIMIT 1');$stmt->bind_param('i',$userId);$stmt->execute();$account=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$account||!password_verify($old,$account['password_hash'])){$message='Kata sandi lama tidak sesuai.';}elseif(strlen($new)<8){$message='Kata sandi baru minimal 8 karakter.';}elseif($new!==$confirm){$message='Konfirmasi kata sandi baru tidak cocok.';}elseif($new===$old){$message='Kata sandi baru harus berbeda dari kata sandi lama.';}else{$hash=password_hash($new,PASSWORD_DEFAULT);$update=$conn->prepare('UPDATE users SET password_hash=? WHERE id=?');$update->bind_param('si',$hash,$userId);$update->execute();$update->close();$_SESSION['flash']=['type'=>'success','message'=>'Kata sandi berhasil diubah.'];header('Location: '.BASE_URL.'/ubah_password.php');exit;}
$_SESSION['flash']=['type'=>'error','message'=>$message];header('Location: '.BASE_URL.'/ubah_password.php');exit;
